436	char **xenbus_directory(struct xenbus_transaction t,
437				const char *dir, const char *node, unsigned int *num)
438	{
439		char *strings, *path;
440		unsigned int len;
441	
442		path = join(dir, node);
443		if (IS_ERR(path))
444			return ERR_CAST(path);
445	
